tools.args:
{"command":"$ErrorActionPreference='Continue'
Write-Output '=== ssh client ==='
(Get-Command ssh -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Source)
ssh -V 2>&1
Write-Output '=== ssh dir ==='
if (Test-Path "$HOME\.ssh") { Get-ChildItem -Force "$HOME\.ssh" | Select-Object Mode,Length,LastWriteTime,Name | Format-Table -AutoSize } else { Write-Output 'NO .ssh DIR' }
Write-Output '=== ssh config ==='
if (Test-Path "$HOME\.ssh\config") { Get-Content "$HOME\.ssh\config" -Encoding UTF8 } else { Write-Output 'NO ssh config' }
Write-Output '---EXIT---'","description":"Проверка ssh-клиента и ключей"}
